/// <summary>Append-only JSON-lines audit log of every call.</summary>
public sealed class AuditLog(string path)
{
    private readonly Lock _gate = new();

    public void Write(string action, string user, bool dryRun, bool ok, long rowsAffected, string? error, string? idempotencyKey, string input)
    {
        var line = JsonSerializer.Serialize(new
        {
            at = DateTimeOffset.Now,
            action,
            user,
            dryRun,
            ok,
            rowsAffected,
            error,
            idempotencyKey,
            input = JsonDocument.Parse(input).RootElement,
        });
        lock (_gate)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);
            File.AppendAllText(path, line + Environment.NewLine);
        }
    }
}

/// <summary>Remembers responses by Idempotency-Key so a retried write is not executed twice.</summary>
public sealed class IdempotencyStore
{
    private readonly string _path;
    private readonly ConcurrentDictionary<string, (string Hash, string Response)> _entries = new(StringComparer.Ordinal);
    private readonly ConcurrentDictionary<string, SemaphoreSlim> _locks = new(StringComparer.Ordinal);
    private readonly Lock _fileGate = new();

    public IdempotencyStore(string path)
    {
        _path = path;
        if (File.Exists(path))
        {
            foreach (var line in File.ReadAllLines(path).Where(l => l.Length > 0))
            {
                var e = JsonSerializer.Deserialize<Entry>(line);
                if (e is not null)
                {
                    _entries[e.Key] = (e.Hash, e.Response);
                }
            }
        }
    }

    private sealed record Entry(string Key, string Hash, string Response);

    public static string Hash(string action, string input) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(action + "\n" + input)));

    public async Task<IDisposable> AcquireAsync(string key, CancellationToken ct)
    {
        var gate = _locks.GetOrAdd(key, _ => new SemaphoreSlim(1, 1));
        await gate.WaitAsync(ct);
        return new Release(gate);
    }

    public bool TryGet(string key, out (string Hash, string Response) entry) => _entries.TryGetValue(key, out entry);

    public void Save(string key, string hash, string response)
    {
        _entries[key] = (hash, response);
        lock (_fileGate)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(_path))!);
            File.AppendAllText(_path, JsonSerializer.Serialize(new Entry(key, hash, response)) + Environment.NewLine);
        }
    }

    private sealed class Release(SemaphoreSlim gate) : IDisposable
    {
        public void Dispose() => gate.Release();
    }
}

/// <summary>API-key authentication. Configuration holds SHA-256 hashes of keys, never the keys.</summary>
public sealed class ApiKeyAuthentication(IOptionsMonitor<AuthenticationSchemeOptions> options, ILoggerFactory logger, UrlEncoder encoder, IConfiguration configuration)
