    public const string Header = "X-Api-Key";

    public static string Hash(string key) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(key)));

    private static string[] Hashes(IConfiguration configuration) =>
        [.. configuration.GetSection("Hokusai:Auth:ApiKeyHashes").GetChildren().Select(c => c.Value).OfType<string>().Where(v => v.Length > 0)];

    public static void EnsureConfigured(IConfiguration configuration)
    {
        if (Hashes(configuration).Length == 0)
        {
            throw new InvalidOperationException("No API keys configured. Run with 'hash-key <key>' and store the hash as Hokusai:Auth:ApiKeyHashes:0, or set Hokusai:Auth:Mode=Windows.");
        }
    }

    protected override Task<AuthenticateResult> HandleAuthenticateAsync()
    {
        if (!Request.Headers.TryGetValue(Header, out var values) || values.ToString().Length == 0)
        {
            return Task.FromResult(AuthenticateResult.NoResult());
        }

        var presented = Encoding.ASCII.GetBytes(Hash(values.ToString()));
